export type Country = "usa" | "uk" | "germany" | "france" | "russia" | "china" | "world";

export interface LocalizedText {
  fa: string;
  en: string;
}

export interface Leader {
  name: LocalizedText;
  title: LocalizedText;
  startYear: number;
  endYear: number;
  initials: string;
  color: string;
  image?: string;
}

export interface IranEvent {
  title: LocalizedText;
  description?: LocalizedText;
  details?: LocalizedText;
  image?: string;
}

export interface WorldEvent {
  country: Country;
  title: LocalizedText;
  description?: LocalizedText;
  details?: LocalizedText;
  image?: string;
}

export interface YearInfo {
  fa: string;
  en: string;
}

export interface TimelineEntry {
  year: number;
  shamsiYear: string;
  iran?: IranEvent[];
  world?: WorldEvent[];
  yearInfo?: YearInfo;
}

const farsiDigits = ["۰", "۱", "۲", "۳", "۴", "۵", "۶", "۷", "۸", "۹"];

export function toFarsiNumber(num: number): string {
  return num
    .toString()
    .split("")
    .map((d) => farsiDigits[parseInt(d)] ?? d)
    .join("");
}

export function gregorianToShamsi(year: number): number {
  return year - 621;
}

